#!/bin/bash
# Build script for theSpeaker (3 boards)
# Target: esp32c3
# Auto-generated by Embedded Generator

set -e

# Check if ESP-IDF is set up
if [ -z "$IDF_PATH" ]; then
    echo "ERROR: ESP-IDF environment not set up."
    echo "Please run: . $HOME/esp/esp-idf/export.sh"
    exit 1
fi

# Set target (only needed once per project)
echo "Setting target to esp32c3..."
idf.py set-target esp32c3

# Build the project
echo "Building theSpeaker (3 boards)..."
idf.py build

echo ""
echo "Build complete! Binary located at: build/thespeaker_3_boards.bin"
echo "To flash: ./flash.sh [PORT]"
